package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetParent;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The rates a sheet's figures use: its own, then, for a grade and date it has none in force on, its
 * parent's, its parent's parent's, up to {@link SheetParent#LEVELS} levels up.
 */
@Service
public class InheritedRates {

    private final RateRepository rates;
    private final RateLogRepository log;
    private final SheetParentRepository parents;

    public InheritedRates(RateRepository rates, RateLogRepository log, SheetParentRepository parents) {
        this.rates = rates;
        this.log = log;
        this.parents = parents;
    }

    /** The sheet's rates and its ancestors', as they are now. */
    @Transactional(readOnly = true)
    public RateLevels of(String sheetId) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        levels.add(byGrade(rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)));
        levels.addAll(ancestors(sheetId));
        return new RateLevels(levels);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade, as they are now. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestors(String sheetId) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        for (String ancestor : parents.ancestorsOf(sheetId, SheetParent.LEVELS)) {
            levels.add(byGrade(rates.findBySheetIdOrderByGradeAscFromDateAsc(ancestor)));
        }
        return levels;
    }

    /** The sheet's rates and its ancestors', each as they stood at the end of the date ({@link #asOf(String, LocalDate)}). */
    @Transactional(readOnly = true)
    public RateLevels levelsAsOf(String sheetId, LocalDate date) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        levels.add(asOf(sheetId, date));
        levels.addAll(ancestorsAsOf(sheetId, date));
        return new RateLevels(levels);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade as they stood at the end of the date. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestorsAsOf(String sheetId, LocalDate date) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        for (String ancestor : parents.ancestorsOf(sheetId, SheetParent.LEVELS)) levels.add(asOf(ancestor, date));
        return levels;
    }

    /**
     * A sheet's rates by grade as they stood at the end of the date: of those set while its today was
     * on or before it, the last set for each grade and from-date (its newest version then).
     */
    @Transactional(readOnly = true)
    public Map<String, List<Rate>> asOf(String sheetId, LocalDate date) {
        Map<String, Map<Optional<LocalDate>, Rate>> then = new LinkedHashMap<>();
        for (RateLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
            if (!line.setBy(date)) continue;
            Map<Optional<LocalDate>, Rate> grade = then.computeIfAbsent(line.getGrade(), g -> new LinkedHashMap<>());
            Optional<LocalDate> from = Optional.ofNullable(line.getFromDate());
            Rate replaced = grade.get(from);
            grade.put(from, line.toRate(replaced == null ? 1 : replaced.getVersions() + 1));
        }
        Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
        then.forEach((grade, rates) -> byGrade.put(grade, new ArrayList<>(rates.values())));
        return byGrade;
    }

    private static Map<String, List<Rate>> byGrade(List<Rate> list) {
        Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
        for (Rate rate : list) byGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        return byGrade;
    }
}
package net.officefloor.hq.app.sheet;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.data.jpa.repository.JpaRepository;

public interface SheetParentRepository extends JpaRepository<SheetParent, String> {

    /** The links of the sheets naming the sheet as their parent. */
    List<SheetParent> findByParentSheet(String parentSheet);

    /** The sheet's children, their children and so on, each once, never the sheet itself. */
    default List<String> descendantsOf(String sheetId) {
        List<String> descendants = new ArrayList<>();
        for (int i = -1; i < descendants.size(); i++) {
            String at = i < 0 ? sheetId : descendants.get(i);
            for (SheetParent link : findByParentSheet(at)) {
                String child = link.getChildSheet();
                if (!child.equals(sheetId) && !descendants.contains(child)) descendants.add(child);
            }
        }
        return descendants;
    }

    /** The topmost ancestor of the sheet (the sheet itself when it names no parent). */
    default String rootOf(String sheetId) {
        String root = sheetId;
        Set<String> seen = new HashSet<>(Set.of(sheetId));
        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) root = at;
        return root;
    }

    /** Every sheet of the sheet's tree: its topmost ancestor, then every descendant of that, each once. */
    default List<String> treeOf(String sheetId) {
        String root = rootOf(sheetId);
        List<String> tree = new ArrayList<>(List.of(root));
        tree.addAll(descendantsOf(root));
        return tree;
    }

    /** The sheet's parent; null when it names none. */
    default String parentOf(String sheetId) {
        return findById(sheetId).map(SheetParent::getParentSheet).orElse(null);
    }

    /** The sheet's parent, its parent's parent and so on, nearest first, at most {@code levels} of them. */
    default List<String> ancestorsOf(String sheetId, int levels) {
        List<String> ancestors = new ArrayList<>();
        String at = sheetId;
        while (ancestors.size() < levels) {
            at = parentOf(at);
            if (at == null || at.equals(sheetId) || ancestors.contains(at)) break;
            ancestors.add(at);
        }
        return ancestors;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * The sheet a sheet names as its parent (not dated): a grade with no rate in force on a date on the
 * child takes the parent's for that grade and date, then the parent's parent's, up to three levels up.
 * Not one of the sheet's own rows, so viewing a sheet as of a date shows the parent it names now.
 */
@Entity
@Table(name = "sheet_parent")
public class SheetParent {

    /** How many levels up a grade's rate is looked for once the sheet has none in force. */
    public static final int LEVELS = 3;

    @Id
    @Column(name = "child_sheet")
    private String childSheet;

    @Column(name = "parent_sheet", nullable = false)
    private String parentSheet;

    protected SheetParent() {}

    public SheetParent(String childSheet, String parentSheet) {
        this.childSheet = childSheet;
        this.parentSheet = parentSheet;
    }

    public String getChildSheet() { return childSheet; }

    public String getParentSheet() { return parentSheet; }

    public void setParentSheet(String parentSheet) { this.parentSheet = parentSheet; }
}
package net.officefloor.hq.app.sheet;

import java.sql.PreparedStatement;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.sql.DataSource;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.asof.SheetHistory;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A steward clones the sheet to another id, one never used: the clone starts with this sheet's today,
 * settings, roles, rates, holidays, void reasons, templates, people (with their grades, terms, contacts,
 * aliases, holds, retirements, snapshot lines and patrons), pools, periods (all open) and claims (with their status,
 * frozen figures, dates, notes, tags and logs, numbered afresh by the clone's own numbering). Statements,
 * and the figures they bound, are not copied; nor are watches, delegations or the sheet's parent. Rows are
 * copied column by column as the store holds them, so a column added later is copied too.
 */
@Service
public class SheetCloneService {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final SettingService settings;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RollupService rollup;
    private final SheetHistory history;
    private final Audit audit;

    public SheetCloneService(DataSource dataSource, SheetRepository sheets, SettingService settings,
            ClaimRepository claims, ClaimService claimService, RollupService rollup, SheetHistory history,
            Audit audit) {
        this.jdbc = new JdbcTemplate(dataSource);
        this.sheets = sheets;
        this.settings = settings;
        this.claims = claims;
